        var header=Join(Text(4,"OsmSchema-V0.6"),Text(4,"DenseNodes"),Int(32,1791678545));var strings=new[]{"",mode=="barrier"?"barrier":mode=="healthcare"?"healthcare":mode=="rail"?"railway":mode=="road"?"highway":mode is "polygon" or "hole"?"natural":"building",mode=="barrier"?"fence":mode=="healthcare"?"clinic":mode=="rail"?"rail":mode=="road"?"residential":mode is "polygon" or "hole"?"water":"yes","name","\u0416\u0438\u0432\u043e\u0439 \u0434\u043e\u043c","natural","water","type","multipolygon","outer","inner","amenity","school"};if(mode is "fuelpump" or "inactivepump"){strings[11]=mode=="fuelpump"?"man_made":"disused:man_made";strings[12]="fuel_pump";}if(mode=="closedfuel"){strings[1]="disused:amenity";strings[2]="fuel";}var table=Join(strings.Select(v=>Text(1,v)).ToArray());
        long[] lat=mode is "road" or "rail"?[547830000,547830000]:mode is "polygon" or "hole" or "split"?[547700000,547950000,547950000,547700000]:[547780000,547880000,547880000,547780000];long[] lon=mode is "road" or "rail"?[320470000,320570000]:mode is "polygon" or "hole" or "split"?[320400000,320400000,320650000,320650000]:[320470000,320470000,320570000,320470000];if(mode=="hole"){lat=[..lat,547810000,547850000,547850000,547810000];lon=[..lon,320490000,320490000,320550000,320550000];}if(mode=="missing"){lat=lat[..3];lon=lon[..3];}
        static long[] Delta(long[] values){long previous=0;return values.Select(v=>{var d=v-previous;previous=v;return d;}).ToArray();}
        var dense=Join(Pack(1,Delta(Enumerable.Range(100,lat.Length).Select(i=>(long)i).ToArray()),true),Pack(8,Delta(lat),true),Pack(9,Delta(lon),true));if(mode is "poi" or "fuelpump" or "inactivepump")dense=Join(dense,Pack(10,[11,12,0,0,0,0]));var primaryRefs=mode is "road" or "rail"?new long[]{100,101}:mode=="split"?[100,101,102]:new long[]{100,101,102,103,100};var tags=mode=="split"?Array.Empty<byte>():Join(Pack(2,[1,3]),Pack(3,[2,4]));var way=Join(Int(1,77),tags,Pack(8,Delta(primaryRefs),true));var waterRefs=mode=="hole"?new long[]{104,105,106,107,104}:mode=="split"?[102,103,100]:new long[]{100,101,102,103,100};var water=Join(Int(1,88),Pack(8,Delta(waterRefs),true));var members=mode is "hole" or "split"?new long[]{77,88}:incomplete?[88,999]:new long[]{88};var roles=mode=="hole"?new long[]{9,10}:members.Select(_=>9L).ToArray();var relation=Join(Int(1,9),Pack(2,[5,7]),Pack(3,[6,8]),Pack(8,roles),Pack(9,Delta(members),true),Pack(10,members.Select(_=>1L).ToArray()));
        var group=mode is "road" or "rail" or "polygon" or "missing" or "barrier" or "healthcare"?Join(Bytes(2,dense),Bytes(3,way)):Join(Bytes(2,dense),Bytes(3,way),Bytes(3,water),Bytes(4,relation));var block=Join(Bytes(1,table),Bytes(2,group));return Join(Frame("OSMHeader",header),Frame("OSMData",block));
